const routes=[{id:'DEL-BOM',name:'Delhi → Mumbai',base:5000,weight:.25},{id:'DEL-BLR',name:'Delhi → Bengaluru',base:6500,weight:.20},{id:'BLR-BOM',name:'Bengaluru → Mumbai',base:4200,weight:.18},{id:'DEL-CCU',name:'Delhi → Kolkata',base:5400,weight:.15},{id:'BOM-HYD',name:'Mumbai → Hyderabad',base:3800,weight:.12},{id:'DEL-MAA',name:'Delhi → Chennai',base:6200,weight:.10}];
const horizons=[1,7,15,30,45],providers=['IndiGo','Air India','MakeMyTrip','Cleartrip','EaseMyTrip','Ixigo'],airlines=['IndiGo','Air India','Akasa Air','SpiceJet','IndiGo','Air India'];
let horizon=7,observations=[],live=false,api='',requestId=0;
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number.isFinite(n)?'₹'+Math.round(n).toLocaleString('en-IN'):'—';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function plusDate(day,n){const d=new Date(day+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function dateLabel(day){return new Date(day+'T00:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'})}
function indiaDay(iso){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(iso))}
function demo(){observations=routes.flatMap((r,ri)=>horizons.flatMap((h,hi)=>providers.map((source,i)=>({id:`${r.id}-${h}-${i}`,route:r.id,horizon:h,airline:airlines[i],flight:['6E 214','AI 805','QP 112','SG 815','6E 612','AI 665'][i],source,fare:Math.round(r.base*([1.43,1.09,.96,.84,.88][hi]+(i-2)*.047+ri*.016)/10)*10,departureDate:plusDate($('#date').value,h),observedAt:$('#date').value+'T06:00:00Z'}))));}
function selectRows(r,h){return observations.filter(o=>o.route===r&&o.horizon===h)}
function index(r,h){const rows=selectRows(r.id,h);return rows.length?100*Math.exp(rows.reduce((sum,o)=>sum+Math.log(o.fare/r.base),0)/rows.length):NaN}
function national(h){return routes.every(r=>selectRows(r.id,h).length)?routes.reduce((s,r)=>s+r.weight*index(r,h),0):NaN}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
function chart(r){const groups=horizons.map(h=>selectRows(r.id,h));if(groups.some(g=>!g.length)){$('#chart').innerHTML='<p style="padding:70px 20px;text-align:center">A complete set of horizons is needed to display this chart.</p>';return}const av=groups.map(a=>a.reduce((s,o)=>s+o.fare,0)/a.length),lo=groups.map(a=>Math.min(...a.map(o=>o.fare)));const max=Math.ceil(Math.max(...av,r.base)/2000)*2000, W=650,H=235,x=i=>65+i*137,y=n=>190-n/max*155;let svg='<svg viewBox="0 0 650 235" role="img" aria-label="Average and lowest fares by advance purchase horizon">';for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="60" x2="622" y1="${y(v)}" y2="${y(v)}" stroke="#ddd6c9"/><text x="0" y="${y(v)+4}" fill="#746f64" font-size="11">₹${(v/1000).toFixed(1)}k</text>`}const points=arr=>arr.map((v,i)=>`${x(i)},${y(v)}`).join(' ');svg+=`<defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#087f62" stop-opacity=".13"/><stop offset="100%" stop-color="#087f62" stop-opacity="0"/></linearGradient></defs><polygon points="${x(0)},190 ${points(av)} ${x(4)},190" fill="url(#fill)"/><line x1="60" x2="622" y1="${y(r.base)}" y2="${y(r.base)}" stroke="#8c8578" stroke-dasharray="5 5"/>`;[av,lo].forEach((arr,j)=>{const c=j?'#4889bd':'#087f62';svg+=`<polyline points="${points(arr)}" fill="none" stroke="${c}" stroke-width="2.5" stroke-linejoin="round"/>`;arr.forEach((v,i)=>svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="white" stroke="${c}" stroke-width="2"><title>T+${horizons[i]}: ${money(v)}</title></circle>`)});horizons.forEach((h,i)=>svg+=`<text x="${x(i)}" y="219" text-anchor="middle" fill="#746f64" font-size="11">T + ${h}</text>`);$('#chart').innerHTML=svg+'</svg>'}
function render(){const r=routes.find(r=>r.id===$('#route').value),rows=selectRows(r.id,horizon),n=national(horizon),ix=index(r,horizon),lowest=rows.length?rows.reduce((a,b)=>a.fare<b.fare?a:b):null;$('#national').textContent=Number.isFinite(n)?n.toFixed(2):'—';$('#nationalChange').textContent=Number.isFinite(n)?`${n>=100?'+':''}${(n-100).toFixed(2)}%`:'Incomplete basket';$('#lowest').textContent=money(lowest?.fare);$('#lowestSource').textContent=lowest?`${lowest.airline} · T+${horizon}`:'No observations';$('#routeindex').textContent=Number.isFinite(ix)?ix.toFixed(2):'—';$('#routeChange').textContent=`${r.id.replace('-',' → ')} · Base ${money(r.base)}`;$('#observations').textContent=rows.length.toString().padStart(2,'0');$('#coverage').textContent=`${new Set(rows.map(o=>o.source)).size} sources · selected route & horizon`;$('#chart-caption').textContent=r.name+' · '+dateLabel($('#date').value);chart(r);$('#indexbars').innerHTML=horizons.map(h=>{const n=national(h);return `<div class="index-row"><span>T + ${h}</span><div class="bar-track"><div class="bar-fill" style="width:${Number.isFinite(n)?Math.min(n/180*100,100):0}%"></div></div><strong>${Number.isFinite(n)?n.toFixed(1):'—'}</strong></div>`}).join('');$('#horizons').innerHTML=horizons.map(h=>`<button class="${h===horizon?'active':''}" data-h="${h}" aria-pressed="${h===horizon}">T + ${h}</button>`).join('');document.querySelectorAll('[data-h]').forEach(b=>b.onclick=()=>{horizon=Number(b.dataset.h);render()});const source=$('#source').value,filtered=rows.filter(o=>source==='all'||o.source===source).sort((a,b)=>a.fare-b.fare);$('#farebody').innerHTML=filtered.length?filtered.map(o=>`<tr><td><span class="airline-logo">${esc(o.airline.slice(0,2).toUpperCase())}</span><span>${esc(o.airline)}<small class="flight">${esc(o.flight)}</small></span></td><td>${esc(o.source)}</td><td>${dateLabel(o.departureDate)}</td><td class="fare">${money(o.fare)}</td><td>${(o.fare/r.base).toFixed(3)}×</td><td><span class="valid">✓ Valid</span></td></tr>`).join(''):'<tr><td colspan="6">No observations match this selection.</td></tr>';$('#table-count').textContent=`${filtered.length} observations · departure ${dateLabel(plusDate($('#date').value,horizon))}`;document.querySelector('.demo').textContent=live?'API DATA · DEMO WEIGHTS':'DEMO DATA';$('#mode-title').textContent=live?'Connected observations':'Prototype workspace';$('#mode-detail').textContent=live?'Fares loaded from your API. Index base fares and weights remain illustrative.':'Illustrative fares and route weights. Connect your collection API for live observations.';renderSources();if($('#freshness'))$('#freshness').textContent=live?'Latest observation: '+new Date(Math.max(...observations.map(o=>Date.parse(o.observedAt)))).toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit'})+' IST':'Illustrative observations';}
function renderSources(){const names=[...new Set([...providers,...observations.map(o=>o.source)])];$('#sourcecards').innerHTML=names.map(p=>{const list=observations.filter(o=>o.source===p);return `<div class="route-card"><h3>${esc(p)}</h3><p>${live?(list.length?'API observations received':'No observations received'):'Demo coverage · not connected'}</p><small>${list.length} observations${live&&list.length?'<br>Latest: '+esc(new Date(Math.max(...list.map(o=>Date.parse(o.observedAt)))).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))+' IST':''}</small></div>`}).join('')}
function refreshSources(){const selected=$('#source').value;$('#source').innerHTML='<option value="all">All sources</option>'+[...new Set(observations.map(o=>o.source))].map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');if([...$('#source').options].some(o=>o.value===selected))$('#source').value=selected}
function validate(data){if(!data||!Array.isArray(data.observations))throw Error('Expected an observations array in the API response.');const seen=new Set();let rejected=0;const rows=data.observations.filter(o=>{const ok=o&&typeof o.id==='string'&&!seen.has(o.id)&&routes.some(r=>r.id===o.route)&&horizons.includes(o.horizon)&&typeof o.fare==='number'&&Number.isFinite(o.fare)&&o.fare>0&&['airline','flight','source'].every(k=>typeof o[k]==='string'&&o[k].trim())&&typeof o.observedAt==='string'&&Number.isFinite(Date.parse(o.observedAt))&&indiaDay(o.observedAt)===$('#date').value&&o.departureDate===plusDate($('#date').value,o.horizon);if(ok)seen.add(o.id);else rejected++;return ok});if(!rows.length)throw Error('No valid, comparable observations for the selected date.');return {rows,rejected}}
async function load(endpoint){const url=new URL(endpoint);if(url.protocol!=='https:')throw Error('Use a secure HTTPS endpoint.');url.searchParams.set('observation_date',$('#date').value);url.searchParams.set('horizons',horizons.join(','));const thisRequest=++requestId;const response=await fetch(url,{signal:AbortSignal.timeout(20000),credentials:'omit',headers:{Accept:'application/json',...(window.collectorAuth?.(url)||{})}});if(!response.ok)throw Error(`Collection API returned status ${response.status}.`);const payload=await response.json();const result=validate(payload);if(thisRequest!==requestId)return false;observations=result.rows;live=payload.mode!=='demo';api=endpoint;refreshSources();render();toast(`${result.rows.length} observations loaded${result.rejected?`; ${result.rejected} invalid or duplicate records excluded`:''}.`);return true}
$('#date').value=today();$('#date').max=today();$('#route').innerHTML=routes.map(r=>`<option value="${r.id}">${r.name} (${r.id})</option>`).join('');$('#routecards').innerHTML=routes.map(r=>`<div class="route-card"><h3>${r.id.replace('-',' → ')}</h3><p>${r.name}</p><small>Base fare ${money(r.base)} · Weight ${Math.round(r.weight*100)}%</small><br><button class="button" data-route="${r.id}">Explore route →</button></div>`).join('');function view(name){['overview','features','routes','automation','sources','method'].forEach(n=>$('#'+n).hidden=n!==name);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));const names={features:['From fare to insight.','The features and methodology behind AeroStat.','Features'],overview:['Airfares. In plain sight.','A single view of Indian routes, fares and booking horizons.','Overview'],automation:['Set the pace. Collect daily.','Plan, collect, validate and track your daily fare basket.','Automation'],routes:['Every route. Every horizon.','Explore the representative route basket.','Route explorer'],sources:['Every fare. A source.','Observation coverage across airlines and booking platforms.','Data sources'],method:['An index you can explain.','The calculation behind AeroStat.','Index methodology']};$('#title').textContent=names[name][0];$('#subtitle').textContent=names[name][1];$('#crumb').textContent=names[name][2]}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{$('#route').value=b.dataset.route;render();view('overview')});$('#route').onchange=render;$('#source').onchange=render;$('#date').onchange=()=>{if(!$('#date').value){$('#date').value=today()}requestId++;if(api){observations=[];render();toast('Date changed. Refresh to load observations for this day.')}else{demo();render()}};
$('#refresh').onclick=async()=>{const b=$('#refresh');b.disabled=true;b.textContent='Loading…';try{if(api)await load(api);else{demo();render();toast('Demo observations refreshed. Connect an API for real fares.')}}catch(e){toast('Unable to load: '+e.message)}finally{b.disabled=false;b.textContent='↻ Refresh observations'}};
function openConnect(){try{$('#endpoint').value=api||localStorage.getItem('aerostat-endpoint')||''}catch{}$('#api-error').textContent='';$('#connection').showModal()}$('#connect').onclick=openConnect;$('.connect-button').onclick=openConnect;$('#close').onclick=()=>$('#connection').close();$('#api-form').onsubmit=async e=>{e.preventDefault();const b=$('#api-form button[type="submit"]');b.disabled=true;b.textContent='Connecting…';$('#api-error').textContent='';try{const ep=$('#endpoint').value.trim();if(await load(ep)){try{localStorage.setItem('aerostat-endpoint',ep)}catch{}$('#connection').close()}}catch(err){$('#api-error').textContent='Could not connect. Check the endpoint, CORS, and response format. '+err.message}finally{b.disabled=false;b.textContent='Connect & load'}};
$('#demo-reset').onclick=()=>{requestId++;live=false;api='';try{localStorage.removeItem('aerostat-endpoint')}catch{}demo();refreshSources();render();$('#connection').close();toast('Demo observations restored.')};$('#export').onclick=()=>{const r=$('#route').value,s=$('#source').value,rows=observations.filter(o=>o.route===r&&o.horizon===horizon&&(s==='all'||o.source===s));if(!rows.length){toast('No observations to export.');return}const keys=['id','route','horizon','airline','flight','source','fare','departureDate','observedAt'],cell=v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"',csv=[keys.join(','),...rows.map(o=>keys.map(k=>cell(o[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`aerostat-${live?'api':'demo'}-${r}-T${horizon}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Selected fare observations exported.')} ;demo();refreshSources();render();

$('#nav-collect').onclick=()=>view('automation');$('.brand').onclick=e=>{e.preventDefault();view('overview')};
